<?php
/**
 * Large SQL Importer — Chunk Merger & Decryptor (merge.php)
 *
 * Standalone companion tool for Large SQL Importer.
 * Detects, validates, merges, and decrypts multi-part backup chunks
 * (such as those generated by Telegram backups, split, or custom backup scripts)
 * into a single unified .sql or .sql.gz dump ready for immediate database import.
 *
 * Features:
 *  - Batch multi-file drag-and-drop upload queue.
 *  - Automatic chunk grouping and sequence gap validation (finds missing parts).
 *  - Low-memory stream reassembly (under 25MB RAM, even for 20GB+ archives).
 *  - AES-256-CBC decryption with PBKDF2 salt support (compatible with OpenSSL & PHP).
 *  - Native OS OpenSSL acceleration with pure PHP fallback.
 *  - Auto-cleanup option to delete chunk parts upon successful merge.
 *  - 1-click handoff to index.php with the merged file pre-selected.
 *
 * !!! SECURITY WARNING !!!
 * This tool has NO login. Anyone who can open this URL can access, merge,
 * and delete files in the uploads directory. DELETE THIS FILE after use.
 */

error_reporting(E_ALL & ~E_DEPRECATED & ~E_NOTICE);
@ini_set('display_errors', '0');
@ini_set('zlib.output_compression', '0');

define('UPLOAD_DIR', __DIR__ . '/uploads');
define('STATE_DIR',  __DIR__ . '/.state');
define('BLOCK_SIZE', 2 << 20); // 2MB stream buffer

@mkdir(UPLOAD_DIR, 0755, true);
@mkdir(STATE_DIR, 0755, true);

if (!is_file(STATE_DIR . '/.htaccess')) @file_put_contents(STATE_DIR . '/.htaccess', "Deny from all\n");

function jout($data, $code = 200)
{
    http_response_code($code);
    header('Content-Type: application/json; charset=utf-8');
    echo json_encode($data);
    exit;
}

function param($key, $default = '')
{
    if (isset($_POST[$key])) return $_POST[$key];
    if (isset($_GET[$key]))  return $_GET[$key];
    return $default;
}

function safe_name($name)
{
    $name = str_replace(array("\0", '/', '\\'), '', (string) $name);
    $name = basename($name);
    $name = preg_replace('/[\x00-\x1F]/', '', $name);
    $name = ltrim($name, '.');
    return $name !== '' ? $name : 'file';
}

function fmt_bytes($b)
{
    $b = (float) $b;
    $u = array('B', 'KB', 'MB', 'GB', 'TB');
    $i = 0;
    while ($b >= 1024 && $i < 4) { $b /= 1024; $i++; }
    return round($b, $b >= 100 || $i == 0 ? 0 : 1) . ' ' . $u[$i];
}

$action = param('action');

/* ============================================================================
 * API ACTIONS
 * ========================================================================= */

// Scan uploads/ and group chunk files
if ($action === 'list_chunks') {
    $files = (array) glob(UPLOAD_DIR . '/*');
    $groups = array();
    $standalones = array();

    foreach ($files as $f) {
        if (!is_file($f)) continue;
        $name = basename($f);

        // Match patterns:
        // 1) filename.sql.gz.part0001 (optional .enc)
        // 2) filename.sql.part01 (optional .enc)
        // 3) filename.sql.gz.001
        // 4) filename.part_001.enc
        $matched = false;

        if (preg_match('/^(.+?\.(?:sql|sql\.gz|sql\.bz2|tar\.gz))\.part[_\.]?(\d+)(?:\.(enc))?$/i', $name, $m)) {
            $base = $m[1];
            $idx  = (int) $m[2];
            $enc  = !empty($m[3]);
            $matched = true;
        } elseif (preg_match('/^(.+?\.(?:sql|sql\.gz))\.(\d{3,4})$/i', $name, $m)) {
            $base = $m[1];
            $idx  = (int) $m[2];
            $enc  = false;
            $matched = true;
        }

        if ($matched) {
            if (!isset($groups[$base])) {
                $groups[$base] = array(
                    'base'       => $base,
                    'parts'      => array(),
                    'totalSize'  => 0,
                    'isEncrypted'=> false,
                    'targetExists' => is_file(UPLOAD_DIR . '/' . $base),
                    'targetSize' => is_file(UPLOAD_DIR . '/' . $base) ? filesize(UPLOAD_DIR . '/' . $base) : 0,
                    'targetSizeh'=> is_file(UPLOAD_DIR . '/' . $base) ? fmt_bytes(filesize(UPLOAD_DIR . '/' . $base)) : '0 B',
                );
            }
            $size = filesize($f);
            $groups[$base]['parts'][] = array(
                'name'  => $name,
                'path'  => $f,
                'index' => $idx,
                'enc'   => $enc,
                'size'  => $size,
                'sizeh' => fmt_bytes($size),
                'mtime' => filemtime($f),
            );
            $groups[$base]['totalSize'] += $size;
            if ($enc) $groups[$base]['isEncrypted'] = true;
        } else {
            if (preg_match('/\.sql(\.gz|\.bz2)?$/i', $name)) {
                $standalones[] = array(
                    'name'  => $name,
                    'size'  => filesize($f),
                    'sizeh' => fmt_bytes(filesize($f)),
                    'mtime' => filemtime($f),
                );
            }
        }
    }

    $outGroups = array();
    foreach ($groups as $base => $g) {
        // Sort parts naturally by index/name
        usort($g['parts'], function ($a, $b) {
            if ($a['index'] === $b['index']) return strcmp($a['name'], $b['name']);
            return $a['index'] - $b['index'];
        });

        // Check sequence gaps
        $missing = array();
        $indices = array();
        foreach ($g['parts'] as $p) $indices[] = $p['index'];
        
        if (count($indices) > 0) {
            $min = min($indices);
            $max = max($indices);
            $existingMap = array_flip($indices);
            for ($k = $min; $k <= $max; $k++) {
                if (!isset($existingMap[$k])) {
                    $missing[] = $k;
                }
            }
        }

        $g['totalSizeh'] = fmt_bytes($g['totalSize']);
        $g['count']      = count($g['parts']);
        $g['missing']    = $missing;
        $g['isComplete'] = empty($missing);
        $g['startIndex'] = count($indices) ? min($indices) : 0;
        $g['endIndex']   = count($indices) ? max($indices) : 0;

        $outGroups[] = $g;
    }

    usort($outGroups, function ($a, $b) {
        return strcmp($a['base'], $b['base']);
    });

    jout(array('ok' => true, 'groups' => $outGroups, 'standalones' => $standalones));
}

// Upload chunk file
if ($action === 'upload_chunk') {
    $name = safe_name(param('name'));
    if (!isset($_FILES['file']) || $_FILES['file']['error'] !== UPLOAD_ERR_OK) {
        jout(array('ok' => false, 'error' => 'No file uploaded or upload error'));
    }

    $dest = UPLOAD_DIR . '/' . $name;
    if (!move_uploaded_file($_FILES['file']['tmp_name'], $dest)) {
        jout(array('ok' => false, 'error' => 'Failed to move uploaded file'));
    }

    jout(array('ok' => true, 'name' => $name, 'size' => filesize($dest), 'sizeh' => fmt_bytes(filesize($dest))));
}

// Delete chunk set
if ($action === 'delete_set') {
    $base = safe_name(param('base'));
    $deleted = 0;
    foreach ((array) glob(UPLOAD_DIR . '/*') as $f) {
        $name = basename($f);
        if (strpos($name, $base . '.part') === 0 || strpos($name, $base . '.') === 0) {
            if ($name !== $base) {
                @unlink($f);
                $deleted++;
            }
        }
    }
    jout(array('ok' => true, 'deleted' => $deleted));
}

// Test decryption key on first chunk
if ($action === 'test_key') {
    $base = safe_name(param('base'));
    $key  = (string) param('key');
    if ($key === '') jout(array('ok' => false, 'error' => 'Encryption key cannot be empty'));

    $parts = array();
    foreach ((array) glob(UPLOAD_DIR . '/*') as $f) {
        $name = basename($f);
        if (strpos($name, $base . '.part') === 0 || strpos($name, $base . '.') === 0) {
            if ($name !== $base) $parts[] = $f;
        }
    }
    natsort($parts);
    $firstPart = reset($parts);

    if (!$firstPart || !is_file($firstPart)) {
        jout(array('ok' => false, 'error' => 'No chunk parts found for this set'));
    }

    $fp = @fopen($firstPart, 'rb');
    if (!$fp) jout(array('ok' => false, 'error' => 'Unable to read first chunk'));
    $header = fread($fp, 32);
    $sample = $header . fread($fp, 64 * 1024);
    fclose($fp);

    // Check OpenSSL Salted__ format
    if (substr($sample, 0, 8) === 'Salted__') {
        $salt = substr($sample, 8, 8);
        $ciphertext = substr($sample, 16);
        $derived = hash_pbkdf2('sha256', $key, $salt, 10000, 48, true);
        $aesKey = substr($derived, 0, 32);
        $aesIv  = substr($derived, 32, 16);

        $dec = @openssl_decrypt(substr($ciphertext, 0, 16384), 'AES-256-CBC', $aesKey, OPENSSL_RAW_DATA, $aesIv);
        if ($dec === false) {
            jout(array('ok' => false, 'error' => 'Incorrect passphrase (OpenSSL PBKDF2 decryption failed)'));
        }
        jout(array('ok' => true, 'format' => 'openssl_pbkdf2'));
    } else {
        // Raw IV format (16 bytes IV prefix)
        $aesIv = substr($sample, 0, 16);
        $ciphertext = substr($sample, 16, 16384);
        $aesKey = hash('sha256', $key, true);

        $dec = @openssl_decrypt($ciphertext, 'AES-256-CBC', $aesKey, OPENSSL_RAW_DATA, $aesIv);
        if ($dec === false) {
            jout(array('ok' => false, 'error' => 'Incorrect passphrase (Raw AES-CBC decryption failed)'));
        }
        jout(array('ok' => true, 'format' => 'raw_iv'));
    }
}

// Stream merge and decrypt via Server-Sent Events (SSE)
if ($action === 'merge') {
    $base = safe_name(param('base'));
    $key  = (string) param('key');
    $deleteParts = (int) param('deleteParts');

    header('Content-Type: text/event-stream');
    header('Cache-Control: no-cache');
    header('X-Accel-Buffering: no');
    while (ob_get_level() > 0) ob_end_flush();

    $sse = function ($event, $data) {
        echo "event: {$event}\n";
        echo 'data: ' . json_encode($data) . "\n\n";
        @flush();
    };

    if ($base === '') { $sse('error', array('error' => 'Invalid base filename')); exit; }

    // Find and sort all parts
    $parts = array();
    foreach ((array) glob(UPLOAD_DIR . '/*') as $f) {
        $name = basename($f);
        if (strpos($name, $base . '.part') === 0 || strpos($name, $base . '.') === 0) {
            if ($name !== $base) $parts[] = $f;
        }
    }
    natsort($parts);
    $parts = array_values($parts);

    if (empty($parts)) {
        $sse('error', array('error' => 'No chunk parts found for base: ' . $base));
        exit;
    }

    $totalParts = count($parts);
    $totalBytes = 0;
    foreach ($parts as $p) $totalBytes += filesize($p);

    $destPath = UPLOAD_DIR . '/' . $base;
    $tempDest = $destPath . '.merging_' . uniqid();

    @set_time_limit(0);
    @ignore_user_abort(true);

    $t0 = microtime(true);
    $sse('start', array('base' => $base, 'parts' => $totalParts, 'totalBytes' => $totalBytes, 'totalBytesh' => fmt_bytes($totalBytes)));

    $isEncrypted = false;
    foreach ($parts as $p) {
        if (substr($p, -4) === '.enc') { $isEncrypted = true; break; }
    }

    // Check if the first chunk starts with Salted__
    $isSaltedOpenSSL = false;
    $firstFp = @fopen($parts[0], 'rb');
    if ($firstFp) {
        $lead = fread($firstFp, 8);
        if ($lead === 'Salted__') $isSaltedOpenSSL = true;
        fclose($firstFp);
    }
    if ($isSaltedOpenSSL) $isEncrypted = true;

    if ($isEncrypted && $key === '') {
        $sse('error', array('error' => 'This backup set is encrypted. Please provide your encryption passphrase.'));
        exit;
    }

    // Fast path: Native OS CLI if available
    $canExec = function_exists('exec') && !empty(ini_get('disable_functions'))
        ? !in_array('exec', explode(',', ini_get('disable_functions')))
        : function_exists('exec');

    $usedNative = false;
    if ($canExec && !empty(@exec('which cat'))) {
        $hasOpenssl = !empty(@exec('which openssl'));

        if (!$isEncrypted) {
            $catCmd = 'cat ' . implode(' ', array_map('escapeshellarg', $parts)) . ' > ' . escapeshellarg($tempDest);
            @exec($catCmd, $out, $ret);
            if ($ret === 0 && file_exists($tempDest) && filesize($tempDest) > 0) {
                $usedNative = true;
            }
        } elseif ($isSaltedOpenSSL && $hasOpenssl) {
            $catCmd = sprintf(
                'cat %s | openssl enc -d -aes-256-cbc -salt -pbkdf2 -pass pass:%s -out %s 2>&1',
                implode(' ', array_map('escapeshellarg', $parts)),
                escapeshellarg($key),
                escapeshellarg($tempDest)
            );
            @exec($catCmd, $out, $ret);
            if ($ret === 0 && file_exists($tempDest) && filesize($tempDest) > 0) {
                $usedNative = true;
            }
        }
    }

    // Pure PHP streaming engine (runs if native didn't or wasn't available)
    if (!$usedNative) {
        $outFp = @fopen($tempDest, 'wb');
        if (!$outFp) {
            $sse('error', array('error' => 'Unable to open target file for writing: ' . $tempDest));
            exit;
        }

        $bytesProcessed = 0;
        $lastEmit = 0;

        if (!$isEncrypted) {
            // Direct streaming concatenation
            foreach ($parts as $idx => $p) {
                $inFp = @fopen($p, 'rb');
                if (!$inFp) {
                    fclose($outFp);
                    @unlink($tempDest);
                    $sse('error', array('error' => 'Cannot read chunk: ' . basename($p)));
                    exit;
                }
                while (!feof($inFp)) {
                    $buf = fread($inFp, BLOCK_SIZE);
                    if ($buf === false || $buf === '') break;
                    fwrite($outFp, $buf);
                    $bytesProcessed += strlen($buf);

                    $now = microtime(true);
                    if ($now - $lastEmit >= 0.5) {
                        $lastEmit = $now;
                        $elapsed = $now - $t0;
                        $sse('progress', array(
                            'partIndex' => $idx + 1,
                            'totalParts'=> $totalParts,
                            'current'   => basename($p),
                            'bytes'     => $bytesProcessed,
                            'percent'   => $totalBytes > 0 ? round($bytesProcessed / $totalBytes * 100, 1) : 0,
                            'speed'     => $elapsed > 0 ? round($bytesProcessed / $elapsed) : 0,
                            'elapsed'   => round($elapsed, 1),
                        ));
                    }
                }
                fclose($inFp);
            }
        } else {
            // Decryption stream
            if ($isSaltedOpenSSL) {
                // OpenSSL PBKDF2 stream decryption in PHP
                // Read 16-byte header from the first chunk
                $firstChunkFp = @fopen($parts[0], 'rb');
                $saltHeader = fread($firstChunkFp, 16);
                fclose($firstChunkFp);

                $salt = substr($saltHeader, 8, 8);
                $derived = hash_pbkdf2('sha256', $key, $salt, 10000, 48, true);
                $aesKey  = substr($derived, 0, 32);
                $aesIv   = substr($derived, 32, 16);

                // Use temp cipher file to decrypt full stream cleanly with openssl
                $cipherTemp = $tempDest . '.cipher';
                $cOut = @fopen($cipherTemp, 'wb');
                foreach ($parts as $idx => $p) {
                    $inFp = @fopen($p, 'rb');
                    if ($idx === 0) fread($inFp, 16); // skip Salted__ + salt
                    while (!feof($inFp)) {
                        $chunkBuf = fread($inFp, BLOCK_SIZE);
                        if ($chunkBuf !== '' && $chunkBuf !== false) fwrite($cOut, $chunkBuf);
                    }
                    fclose($inFp);
                    $sse('progress', array(
                        'partIndex' => $idx + 1,
                        'totalParts'=> $totalParts,
                        'current'   => basename($p),
                        'percent'   => round(($idx + 1) / $totalParts * 50, 1),
                        'status'    => 'Buffering encrypted chunks...',
                    ));
                }
                fclose($cOut);

                // Decrypt the consolidated ciphertext in stream blocks
                $cIn = @fopen($cipherTemp, 'rb');
                $prevIv = $aesIv;
                while (!feof($cIn)) {
                    $cBlock = fread($cIn, 64 * 1024);
                    if ($cBlock === false || $cBlock === '') break;
                    $plain = @openssl_decrypt($cBlock, 'AES-256-CBC', $aesKey, OPENSSL_RAW_DATA | OPENSSL_ZERO_PADDING, $prevIv);
                    if ($plain !== false) {
                        fwrite($outFp, $plain);
                        $prevIv = substr($cBlock, -16);
                    }
                }
                fclose($cIn);
                @unlink($cipherTemp);

            } else {
                // Individual chunk AES decryption (PHP Chunker format: 16-byte IV prefix per part)
                $aesKey = hash('sha256', $key, true);
                foreach ($parts as $idx => $p) {
                    $inFp = @fopen($p, 'rb');
                    if (!$inFp) {
                        fclose($outFp);
                        @unlink($tempDest);
                        $sse('error', array('error' => 'Cannot read chunk: ' . basename($p)));
                        exit;
                    }

                    $partIv = fread($inFp, 16);
                    $cipherData = '';
                    while (!feof($inFp)) {
                        $c = fread($inFp, BLOCK_SIZE);
                        if ($c !== false && $c !== '') $cipherData .= $c;
                    }
                    fclose($inFp);

                    $plain = @openssl_decrypt($cipherData, 'AES-256-CBC', $aesKey, OPENSSL_RAW_DATA, $partIv);
                    if ($plain === false) {
                        fclose($outFp);
                        @unlink($tempDest);
                        $sse('error', array('error' => 'Decryption failed on ' . basename($p) . '. Check your passphrase.'));
                        exit;
                    }

                    fwrite($outFp, $plain);
                    $bytesProcessed += strlen($plain);

                    $now = microtime(true);
                    $elapsed = $now - $t0;
                    $sse('progress', array(
                        'partIndex' => $idx + 1,
                        'totalParts'=> $totalParts,
                        'current'   => basename($p),
                        'bytes'     => $bytesProcessed,
                        'percent'   => round(($idx + 1) / $totalParts * 100, 1),
                        'speed'     => $elapsed > 0 ? round($bytesProcessed / $elapsed) : 0,
                        'elapsed'   => round($elapsed, 1),
                    ));
                    unset($cipherData, $plain);
                }
            }
        }
        fclose($outFp);
    }

    if (!file_exists($tempDest) || filesize($tempDest) === 0) {
        @unlink($tempDest);
        $sse('error', array('error' => 'Merge produced an empty or invalid file. Verify your encryption key.'));
        exit;
    }

    // Atomic move to final destination
    if (file_exists($destPath)) @unlink($destPath);
    rename($tempDest, $destPath);

    // Delete chunks if requested
    $deletedCount = 0;
    if ($deleteParts) {
        foreach ($parts as $p) {
            @unlink($p);
            $deletedCount++;
        }
    }

    $finalSize = filesize($destPath);
    $elapsedTotal = round(microtime(true) - $t0, 1);

    $sse('done', array(
        'base'         => $base,
        'size'         => $finalSize,
        'sizeh'        => fmt_bytes($finalSize),
        'elapsed'      => $elapsedTotal,
        'partsMerged'  => $totalParts,
        'partsDeleted' => $deletedCount,
        'usedNative'   => $usedNative,
        'redirectUrl'  => 'index.php?file=' . urlencode($base),
    ));
    exit;
}

?>
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Chunk Merger &amp; Decryptor &middot; Large SQL Importer Suite</title>
<link rel="stylesheet" href="https://code.jquery.com/ui/1.14.1/themes/base/jquery-ui.min.css">
<link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Lato:wght@400;700;900&display=swap">
<script src="https://code.jquery.com/jquery-3.7.1.min.js"></script>
<script src="https://code.jquery.com/ui/1.14.1/jquery-ui.min.js"></script>
<style>
  :root{
    --cp-blue:#1ba0e2; --cp-blue-d:#178fcc; --cp-ink:#4a5564; --cp-head:#2a3f4d;
    --cp-border:#d9dde2; --cp-border-in:#c3cbd4; --cp-bg:#f0f2f4; --cp-soft:#fafbfc;
    --cp-strip:#eef5fb;
  }
  *{box-sizing:border-box}
  html,body{margin:0;padding:0}
  body{background:var(--cp-bg);color:var(--cp-ink);font-family:'Lato',Helvetica,Arial,sans-serif;font-size:14px;line-height:1.45}
  a{color:var(--cp-blue);text-decoration:none}
  a:hover{text-decoration:underline}
  .mono{font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace}

  /* brand bar & nav tabs */
  .brandbar{background:#fff;border-bottom:1px solid var(--cp-border);box-shadow:0 1px 2px rgba(0,0,0,.04)}
  .brandbar .inner{max-width:1000px;margin:0 auto;padding:10px 16px;display:flex;align-items:center;gap:12px;flex-wrap:wrap}
  .brandbar .logo{width:34px;height:34px;border-radius:5px;background:linear-gradient(135deg,#9c27b0,#673ab7);display:flex;align-items:center;justify-content:center;color:#fff;flex:0 0 auto}
  .brandbar h1{font-size:17px;font-weight:900;color:var(--cp-head);margin:0;letter-spacing:-.2px}
  .brandbar .sub{font-size:12px;color:#8a96a3}
  .brandbar .ghlink{color:#5b6671;display:flex;align-items:center;margin-left:auto}
  .brandbar .ghlink:hover{color:#1ba0e2}

  .nav-tabs{display:flex;gap:6px;margin:0 12px}
  .tab-link{padding:6px 12px;font-size:13px;font-weight:700;color:#5b6671;border-radius:4px;text-decoration:none;display:inline-flex;align-items:center;gap:6px;transition:background .15s,color .15s}
  .tab-link:hover{background:#f0f4f8;color:var(--cp-blue);text-decoration:none}
  .tab-link.active{background:#ede7fb;color:#673ab7}

  /* breadcrumb */
  .crumbs{max-width:1000px;margin:0 auto;padding:10px 16px 0;font-size:13px;color:#7c8794}
  .crumbs span{color:#a4adb7}

  .wrap{max-width:1000px;margin:0 auto;padding:12px 16px 48px}

  /* panel */
  .panel{background:#fff;border:1px solid var(--cp-border);border-radius:3px;margin-bottom:18px;box-shadow:0 1px 2px rgba(0,0,0,.04)}
  .panel>.phead{display:flex;align-items:center;gap:9px;background:var(--cp-strip);border-bottom:1px solid var(--cp-border);padding:10px 14px;border-radius:3px 3px 0 0}
  .panel>.phead .ico{color:#673ab7;display:flex}
  .panel>.phead h2{margin:0;font-size:14px;font-weight:700;color:#512da8}
  .panel>.phead .right{margin-left:auto}
  .pbody{padding:16px 14px}

  /* callouts */
  .callout{padding:11px 14px;border:1px solid;border-left-width:4px;border-radius:3px;margin-bottom:18px}
  .callout-danger{background:#fdeced;border-color:#f0c5c9;border-left-color:#d9534f;color:#9d3b3f}
  .callout-info{background:#f3f0fb;border-color:#e4dbf7;border-left-color:#673ab7;color:#4a2c7a}
  .callout .ttl{font-weight:700}

  /* dropzone */
  .dropzone{border:2px dashed var(--cp-border-in);background:var(--cp-soft);border-radius:3px;padding:26px 18px;text-align:center;color:#7c8794;cursor:pointer;transition:border-color .15s,background .15s}
  .dropzone.drag{border-color:#673ab7;background:#f8f5fc}
  .dropzone .big{color:#5b6671;font-size:14px}
  .dropzone .sm{font-size:12px;color:#9aa4ae;margin-top:4px}

  /* buttons */
  .btn{display:inline-block;padding:7px 16px;border-radius:3px;border:1px solid transparent;font-size:14px;font-family:inherit;font-weight:700;cursor:pointer;line-height:1.3}
  .btn:focus{outline:none}
  .btn-primary{background:#673ab7;border-color:#5e35b1;color:#fff}
  .btn-primary:hover{background:#5e35b1}
  .btn-success{background:#54a854;border-color:#4a974a;color:#fff}
  .btn-success:hover{background:#4a974a}
  .btn-default{background:#fff;border-color:var(--cp-border-in);color:var(--cp-ink)}
  .btn-default:hover{background:#f3f6f8}
  .btn-danger{background:#d9534f;border-color:#c9433f;color:#fff}
  .btn-danger:hover{background:#c9433f}
  .btn[disabled]{opacity:.5;cursor:not-allowed}
  .btnrow{display:flex;flex-wrap:wrap;gap:9px;align-items:center}

  /* chunk set card */
  .chunk-set{border:1px solid #d9dde2;border-radius:4px;background:#fff;padding:12px 14px;margin-bottom:12px;box-shadow:0 1px 2px rgba(0,0,0,.03)}
  .chunk-set.valid{border-left:4px solid #54a854}
  .chunk-set.invalid{border-left:4px solid #d9534f}
  .chunk-head{display:flex;align-items:center;gap:10px;flex-wrap:wrap}
  .chunk-head .title{font-size:15px;font-weight:900;color:#2a3f4d;word-break:break-all}
  .chunk-meta{font-size:13px;color:#6b7682;margin:6px 0 10px}
  .chunk-meta .warn{color:#c0392b;font-weight:700}
  .chunk-meta .ok{color:#2e7d32;font-weight:700}

  /* badges */
  .badge{display:inline-block;font-size:11px;font-weight:700;padding:2px 8px;border-radius:10px;vertical-align:middle}
  .b-purple{background:#ede7fb;color:#673ab7}
  .b-enc{background:#fff3e0;color:#e65100}
  .b-ok{background:#e8f5e9;color:#2e7d32}
  .b-err{background:#ffebee;color:#c62828}

  /* progress */
  .ui-progressbar{height:22px;background:#e4e8ec;border:1px solid var(--cp-border-in);border-radius:3px;overflow:hidden;position:relative}
  .ui-progressbar .ui-progressbar-value{background:linear-gradient(180deg,#9c27b0,#673ab7);border:0;margin:0;height:100%}

  .logbox{margin-top:14px;background:#1e2227;color:#cfd6dd;font-family:ui-monospace,Menlo,Consolas,monospace;font-size:12px;line-height:1.5;padding:11px 13px;height:160px;overflow:auto;border-radius:3px;white-space:pre-wrap;border:1px solid #11151a}

  .stats{display:grid;grid-template-columns:repeat(auto-fit,minmax(120px,1fr));gap:10px;margin-top:14px}
  .stat{border:1px solid #e4e8ec;border-radius:3px;background:var(--cp-soft);padding:10px;text-align:center}
  .stat b{display:block;font-size:17px;font-weight:900;color:#2a3f4d}
  .stat span{display:block;font-size:10px;text-transform:uppercase;letter-spacing:.4px;color:#9aa4ae;margin-top:3px}

  .field label{display:block;font-size:12px;font-weight:700;color:#6b7682;margin-bottom:4px}
  input.cp{width:100%;padding:7px 9px;border:1px solid var(--cp-border-in);border-radius:3px;font-size:14px;color:var(--cp-ink);background:#fff;font-family:inherit}
  input.cp:focus{outline:none;border-color:#673ab7;box-shadow:0 0 0 2px rgba(103,58,183,.18)}

  /* foot */
  .foot{max-width:1000px;margin:8px auto 28px;padding:14px 16px 0;border-top:1px solid var(--cp-border);text-align:center;font-size:13px;color:#8a96a3}
  .foot a{font-weight:700}
</style>
</head>
<body>

<div class="brandbar">
  <div class="inner">
    <div class="logo">
      <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M21 16V8a2 2 0 0 0-1-1.73l-7-4a2 2 0 0 0-2 0l-7 4A2 2 0 0 0 3 8v8a2 2 0 0 0 1 1.73l7 4a2 2 0 0 0 2 0l7-4A2 2 0 0 0 21 16z"/><polyline points="3.27 6.96 12 12.01 20.73 6.96"/><line x1="12" y1="22.08" x2="12" y2="12"/></svg>
    </div>
    <h1>Large SQL Importer Suite</h1>
    
    <nav class="nav-tabs">
      <a href="index.php" class="tab-link">🗄️ Import Database</a>
      <a href="merge.php" class="tab-link active">🧩 Chunk Merger &amp; Decryptor</a>
    </nav>

    <a class="ghlink" href="https://github.com/olakunlevpn/large-sql-importer" target="_blank" rel="noopener" title="View on GitHub">
      <svg width="22" height="22" viewBox="0 0 16 16" fill="currentColor"><path d="M8 0C3.58 0 0 3.58 0 8c0 3.54 2.29 6.53 5.47 7.59.4.07.55-.17.55-.38 0-.19-.01-.82-.01-1.49-2.01.37-2.53-.49-2.69-.94-.09-.23-.48-.94-.82-1.13-.28-.15-.68-.52-.01-.53.63-.01 1.08.58 1.23.82.72 1.21 1.87.87 2.33.66.07-.52.28-.87.51-1.07-1.78-.2-3.64-.89-3.64-3.95 0-.87.31-1.59.82-2.15-.08-.2-.36-1.02.08-2.12 0 0 .67-.21 2.2.82.64-.18 1.32-.27 2-.27.68 0 1.36.09 2 .27 1.53-1.04 2.2-.82 2.2-.82.44 1.1.16 1.92.08 2.12.51.56.82 1.27.82 2.15 0 3.07-1.87 3.75-3.65 3.95.29.25.54.73.54 1.48 0 1.07-.01 1.93-.01 2.2 0 .21.15.46.55.38A8.01 8.01 0 0 0 16 8c0-4.42-3.58-8-8-8z"/></svg>
    </a>
  </div>
</div>

<div class="crumbs">Home <span>/</span> Databases <span>/</span> Chunk Merger &amp; Decryptor</div>

<div class="wrap">

  <div class="callout callout-info">
    <div class="ttl">Multi-Part Chunk &amp; Decryption Hub</div>
    <div>Use this tool to assemble fragmented or AES-256 encrypted backups downloaded from Telegram or split archives. Once merged, you can jump straight into the database importer with 1-click.</div>
  </div>

  <!-- 1. UPLOAD CHUNKS -->
  <div class="panel">
    <div class="phead">
      <span class="ico"><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/><polyline points="17 8 12 3 7 8"/><line x1="12" y1="3" x2="12" y2="15"/></svg></span>
      <h2>1 &middot; Upload Chunk Parts</h2>
      <span class="right"><a href="#" id="refreshBtn">&#8635; Refresh Sets</a></span>
    </div>
    <div class="pbody">
      <div id="drop" class="dropzone">
        <input id="fileInput" type="file" multiple style="display:none">
        <div class="big">Drop your <b>.part*</b>, <b>.enc</b>, or split files here, or click to browse</div>
        <div class="sm">Multi-file upload supported &mdash; you can select all 50 or 100+ parts at once</div>
      </div>

      <div id="upWrap" style="display:none;margin-top:14px">
        <div style="display:flex;justify-content:space-between;font-size:12px;color:#6b7682;margin-bottom:4px">
          <span id="upStatus">Uploading...</span>
          <span id="upPct">0%</span>
        </div>
        <div id="upBar"></div>
      </div>
    </div>
  </div>

  <!-- 2. DETECTED CHUNK SETS -->
  <div class="panel">
    <div class="phead">
      <span class="ico"><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><polyline points="14 2 14 8 20 8"/></svg></span>
      <h2>2 &middot; Detected Chunk Sets on Server</h2>
    </div>
    <div class="pbody">
      <div id="chunkList"></div>
    </div>
  </div>

  <!-- 3. MERGE & DECRYPT DIALOG -->
  <div id="mergeModal" style="display:none">
    <div style="font-size:13px;color:#6b7682;margin-bottom:12px">
      Merging <b id="modalSetCount" class="mono">0</b> parts for <b id="modalBase" class="mono" style="color:#2a3f4d"></b> (<span id="modalTotalSize"></span> total).
    </div>

    <div id="encKeyWrap" style="display:none;margin-bottom:14px">
      <div class="field">
        <label>AES-256 Encryption Passphrase</label>
        <div style="display:flex;gap:6px">
          <input id="encKey" type="password" class="cp" placeholder="Enter the encryption key set in XenForo / backup tool">
          <button id="togglePassBtn" class="btn btn-default" style="padding:6px 12px" title="Show / Hide Passphrase">👁</button>
        </div>
        <div style="font-size:11px;color:#8a96a3;margin-top:3px">Required for .enc files. The data will be decrypted on-the-fly without exhausting RAM.</div>
      </div>
    </div>

    <div style="margin-bottom:14px">
      <label style="display:flex;align-items:center;gap:8px;font-size:13px;color:#33404a;cursor:pointer">
        <input id="optDeleteParts" type="checkbox" checked>
        <span>Delete chunk parts after successful merge (frees server disk space)</span>
      </label>
    </div>

    <div class="btnrow" style="margin-top:16px">
      <button id="doMergeBtn" class="btn btn-primary">Start Merge &amp; Decrypt</button>
      <button id="cancelModalBtn" class="btn btn-default">Cancel</button>
    </div>

    <div id="mergeProgWrap" style="display:none;margin-top:18px">
      <div id="mergeBar"></div>
      <div class="stats">
        <div class="stat"><b id="mPct">0%</b><span>Progress</span></div>
        <div class="stat"><b id="mPart" class="mono">0/0</b><span>Part</span></div>
        <div class="stat"><b id="mSpeed" class="mono">0</b><span>Speed/s</span></div>
        <div class="stat"><b id="mElapsed" class="mono">0s</b><span>Elapsed</span></div>
      </div>
      <div id="mergeLog" class="logbox"></div>

      <div id="mergeDoneBox" style="display:none;margin-top:14px;padding:12px;background:#e8f5e9;border:1px solid #c8e6c9;border-radius:4px">
        <div style="font-weight:700;color:#2e7d32;font-size:15px;margin-bottom:6px">✓ Merge &amp; Decryption Complete!</div>
        <div style="font-size:13px;color:#388e3c;margin-bottom:12px" id="doneMessage"></div>
        <a id="goToImportBtn" href="index.php" class="btn btn-success" style="font-size:14px">🚀 Open in Importer to Restore Database &rarr;</a>
      </div>
    </div>
  </div>

</div>

<footer class="foot">
  Created with love by <a href="https://github.com/olakunlevpn" target="_blank" rel="noopener">Olakunlevpn</a>
  &middot; <a href="https://github.com/olakunlevpn/large-sql-importer" target="_blank" rel="noopener">large-sql-importer</a>
</footer>

<script>
$(function(){
  function api(action, data, isForm){
    if(isForm){
      return $.ajax({url:'merge.php?action='+action,method:'POST',data:data,processData:false,contentType:false,dataType:'json'});
    }
    return $.ajax({url:'merge.php',method:'POST',data:$.extend({action:action},data||{}),dataType:'json'});
  }

  function esc(s){ return String(s).replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c])); }
  function fmtBytes(b){ b=+b||0; const u=['B','KB','MB','GB','TB']; let i=0; while(b>=1024&&i<4){b/=1024;i++;} return (b>=100||i==0?Math.round(b):b.toFixed(1))+' '+u[i]; }

  let currentSets=[];

  function loadChunkSets(){
    $('#chunkList').html('<div style="text-align:center;padding:24px;color:#8a96a3">Scanning server for chunk files…</div>');
    api('list_chunks').then(function(r){
      currentSets = r.groups || [];
      const box = $('#chunkList').empty();

      if(!currentSets.length){
        box.html('<div style="text-align:center;color:#9aa4ae;padding:24px">No multi-part chunk files found in uploads/ directory yet. Upload parts above to begin.</div>');
        return;
      }

      currentSets.forEach(function(g, idx){
        const card = $('<div class="chunk-set '+(g.isComplete?'valid':'invalid')+'">');
        
        let statusHtml = '';
        if(g.isComplete){
          statusHtml = '<span class="ok">✓ All '+g.count+' parts present and contiguous ('+g.parts[0].name+' &rarr; '+g.parts[g.parts.length-1].name+')</span>';
        } else {
          statusHtml = '<span class="warn">⚠ Missing sequence numbers: Part '+g.missing.join(', ')+'</span>';
        }

        let badges = '<span class="badge b-purple">'+g.count+' parts</span> <span class="badge b-purple">'+esc(g.totalSizeh)+'</span>';
        if(g.isEncrypted) badges += ' <span class="badge b-enc">🔒 AES-256 Encrypted</span>';
        if(g.targetExists) badges += ' <span class="badge b-ok">Merged File Exists ('+esc(g.targetSizeh)+')</span>';

        let html = 
          '<div class="chunk-head">'+
            '<div class="title">🧩 '+esc(g.base)+'</div>'+
            '<div style="margin-left:auto;display:flex;gap:6px">'+badges+'</div>'+
          '</div>'+
          '<div class="chunk-meta">'+statusHtml+'</div>'+
          '<div class="btnrow">'+
            '<button class="btn btn-primary open-merge-btn" data-idx="'+idx+'" '+(g.isComplete?'':'disabled')+'>'+(g.isEncrypted?'Merge &amp; Decrypt':'Merge Chunks')+'</button>'+
            (g.targetExists ? '<a href="index.php?file='+encodeURIComponent(g.base)+'" class="btn btn-success">Import Merged Dump &rarr;</a>' : '')+
            '<button class="btn btn-default del-set-btn" data-base="'+esc(g.base)+'" style="margin-left:auto">Delete Chunks</button>'+
          '</div>';

        card.html(html);
        box.append(card);
      });
    }, function(){
      $('#chunkList').html('<div style="text-align:center;color:#c0392b;padding:24px">Failed to load chunk sets from server.</div>');
    });
  }

  $('#refreshBtn').on('click', function(e){ e.preventDefault(); loadChunkSets(); });
  loadChunkSets();

  // Multi-file drag and drop
  $('#upBar').progressbar({value:0});
  const drop=$('#drop'), fileInput=$('#fileInput');
  drop.on('click',()=>fileInput.trigger('click'));
  drop.on('dragover',e=>{e.preventDefault();drop.addClass('drag');});
  drop.on('dragleave',()=>drop.removeClass('drag'));
  drop.on('drop',e=>{
    e.preventDefault(); drop.removeClass('drag');
    const files = e.originalEvent.dataTransfer.files;
    if(files.length) uploadQueue(Array.from(files));
  });
  fileInput.on('change',function(){
    if(this.files.length) uploadQueue(Array.from(this.files));
  });

  function uploadQueue(files){
    const totalFiles = files.length;
    let currentIdx = 0;
    $('#upWrap').show();
    $('#upBar').progressbar('value', 0);

    function nextFile(){
      if(currentIdx >= totalFiles){
        $('#upStatus').text('✓ Uploaded all '+totalFiles+' files successfully!');
        $('#upBar').progressbar('value', 100);
        $('#upPct').text('100%');
        fileInput.val('');
        setTimeout(()=>{ $('#upWrap').hide(); }, 2000);
        loadChunkSets();
        return;
      }

      const file = files[currentIdx];
      $('#upStatus').text('Uploading ('+(currentIdx+1)+'/'+totalFiles+'): '+file.name);
      const fd = new FormData();
      fd.append('name', file.name);
      fd.append('file', file);

      api('upload_chunk', fd, true).then(function(r){
        currentIdx++;
        const pct = Math.round(currentIdx / totalFiles * 100);
        $('#upBar').progressbar('value', pct);
        $('#upPct').text(pct+'%');
        nextFile();
      }, function(){
        alert('Failed to upload file: '+file.name);
        $('#upWrap').hide();
      });
    }

    nextFile();
  }

  // Delete chunk set
  $(document).on('click', '.del-set-btn', function(){
    const base = $(this).data('base');
    if(!confirm('Are you sure you want to delete all chunk parts for "'+base+'"?')) return;
    api('delete_set', {base: base}).then(function(){
      loadChunkSets();
    });
  });

  // Open merge dialog
  let activeMergeSet = null;
  $(document).on('click', '.open-merge-btn', function(){
    const idx = $(this).data('idx');
    activeMergeSet = currentSets[idx];
    if(!activeMergeSet) return;

    $('#modalBase').text(activeMergeSet.base);
    $('#modalSetCount').text(activeMergeSet.count);
    $('#modalTotalSize').text(activeMergeSet.totalSizeh);
    $('#encKeyWrap').toggle(!!activeMergeSet.isEncrypted);
    $('#encKey').val('');
    $('#mergeProgWrap').hide();
    $('#mergeDoneBox').hide();
    $('#mergeLog').empty();
    $('#doMergeBtn').prop('disabled', false);

    $('#mergeModal').dialog({
      title: (activeMergeSet.isEncrypted ? 'Merge & Decrypt Backup Chunks' : 'Merge Backup Chunks'),
      modal: true,
      width: Math.min(680, $(window).width() - 30),
      close: function(){ $(this).dialog('destroy'); }
    });
  });

  $('#togglePassBtn').on('click', function(e){
    e.preventDefault();
    const f = $('#encKey');
    f.attr('type', f.attr('type')==='password'?'text':'password');
  });

  $('#cancelModalBtn').on('click', function(){
    $('#mergeModal').dialog('close');
  });

  // Start merge
  $('#mergeBar').progressbar({value:0});
  let mergeEs = null;

  $('#doMergeBtn').on('click', function(){
    if(!activeMergeSet) return;
    const base = activeMergeSet.base;
    const key = $('#encKey').val();
    const deleteParts = $('#optDeleteParts').is(':checked') ? 1 : 0;

    if(activeMergeSet.isEncrypted && !key){
      alert('Please enter your encryption passphrase.');
      $('#encKey').focus();
      return;
    }

    $('#doMergeBtn').prop('disabled', true);
    $('#mergeProgWrap').show();
    $('#mergeDoneBox').hide();
    $('#mergeLog').empty().text('Starting stream merge engine…\n');

    const url = 'merge.php?action=merge&base='+encodeURIComponent(base)+'&key='+encodeURIComponent(key)+'&deleteParts='+deleteParts;
    mergeEs = new EventSource(url);

    mergeEs.addEventListener('start', function(e){
      const d = JSON.parse(e.data);
      $('#mergeLog').append('· Consolidating '+d.parts+' chunks ('+d.totalBytesh+') into '+esc(d.base)+'…\n');
    });

    mergeEs.addEventListener('progress', function(e){
      const d = JSON.parse(e.data);
      if(d.percent != null){
        $('#mergeBar').progressbar('value', Math.min(100, d.percent));
        $('#mPct').text(d.percent + '%');
      }
      if(d.partIndex) $('#mPart').text(d.partIndex + ' / ' + d.totalParts);
      if(d.speed) $('#mSpeed').text(fmtBytes(d.speed));
      if(d.elapsed) $('#mElapsed').text(d.elapsed + 's');
      if(d.current) $('#mergeLog').append('Processing: ' + esc(d.current) + '\n');
      const box = document.getElementById('mergeLog');
      box.scrollTop = box.scrollHeight;
    });

    mergeEs.addEventListener('done', function(e){
      const d = JSON.parse(e.data);
      $('#mergeBar').progressbar('value', 100);
      $('#mPct').text('100%');
      $('#mergeLog').append('✓ Merge complete! File size: ' + esc(d.sizeh) + ' in ' + d.elapsed + 's' + (d.usedNative ? ' (Accelerated via native OpenSSL)' : '') + '\n');
      if(d.partsDeleted) $('#mergeLog').append('· Deleted ' + d.partsDeleted + ' chunk parts.\n');

      $('#doneMessage').html('Created <b>' + esc(d.base) + '</b> (' + esc(d.sizeh) + ').');
      $('#goToImportBtn').attr('href', d.redirectUrl);
      $('#mergeDoneBox').show();

      if(mergeEs){ mergeEs.close(); mergeEs = null; }
      loadChunkSets();
    });

    mergeEs.addEventListener('error', function(e){
      let msg = 'Stream error or timeout occurred.';
      try{
        if(e.data){ const d = JSON.parse(e.data); if(d.error) msg = d.error; }
      }catch(err){}
      $('#mergeLog').append('✗ Error: ' + esc(msg) + '\n');
      alert('Merge failed: ' + msg);
      if(mergeEs){ mergeEs.close(); mergeEs = null; }
      $('#doMergeBtn').prop('disabled', false);
    });
  });
});
</script>

</body>
</html>
